insert into iller (id, ad, slug, baslik, aciklama, ozet, metin, sira, aktif) values
  (1, 'Adana', 'adana', 'Adana Evden Eve Nakliyat Firmaları', 'Adana evden eve nakliyat firmaları rehberi. İlçe ilçe firma listesi, telefon, adres ve puanlar. Ücretsiz teklif alın.', 'Adana merkez ve ilçelerde çalışan nakliyat firmalarını adres, telefon ve puanlarıyla listeledik.', '<p>Adana ev taşıma firmaları arasında seçim yaparken bakılması gereken ilk şey, firmanın taşıma yaptığı bölgeyi gerçekten tanıyıp tanımadığıdır. Seyhan''ın dar sokakları, Çukurova''nın yüksek katlı siteleri ve Yüreğir''in geniş bulvarları birbirinden farklı ekipman ister.</p><h3>Fiyatı belirleyen etkenler</h3><ul><li>Evin metrekaresi ve oda sayısı</li><li>Çıkış ve varış katı, binada asansör olup olmadığı</li><li>Dış cephe asansörü gerekip gerekmediği</li><li>Mesafe: şehir içi mi, şehirler arası mı</li><li>Paketleme, montaj-demontaj ve sigorta gibi ek hizmetler</li></ul><h3>Teklif alırken dikkat edin</h3><p>Adana nakliye firmaları çoğunlukla telefonda kaba bir fiyat verir, ancak sağlıklı fiyat için eve gelinip ekspertiz yapılması gerekir. En az üç firmadan teklif alın, fiyatın neyi kapsadığını yazılı isteyin.</p><h3>Sigorta ve sözleşme</h3><p>Adana ev taşıma firmaları arasında taşıma sigortası sunanlar bulunur. Kıymetli eşyanız varsa sigortayı mutlaka talep edin ve sözleşmede eşya listesinin yer aldığından emin olun.</p>', 1, true)
insert into ilceler (id, il_id, ad, slug, baslik, aciklama, ozet, metin, sira, aktif) values
  (1, 1, 'Seyhan', 'seyhan', 'Seyhan Evden Eve Nakliyat Firmaları', 'Adana Seyhan evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Seyhan nakliyat firmaları.', 'Seyhan Adana''nın en yoğun ilçesi ve nakliyat firmalarının büyük bölümü burada. Gürselpaşa, Tellidere, Pınar ve Fatih mahalleleri firma ofislerinin toplandığı bölgeler.', '<p>Seyhan''da taşınırken en sık karşılaşılan sorun sokak darlığı ve park yeri. Reşatbey, Ziyapaşa ve Çınarlı gibi merkez mahallelerde kamyonun kapının önüne yanaşması her zaman mümkün olmuyor; bu yüzden Seyhan''da çalışan Adana taşıma şirketleri çoğunlukla dış cephe asansörüyle iş yapar. Eski yapı stoğunun yoğun olduğu Kurtuluş ve Dağlıoğlu tarafında merdiven boşlukları dar olduğu için mobilyanın demonte edilmesi gerekir. Taşınma tarihini hafta içi seçmeniz hem trafiği hem de fiyatı olumlu etkiler.</p>', 1, true),
  (2, 1, 'Çukurova', 'cukurova', 'Çukurova Evden Eve Nakliyat Firmaları', 'Adana Çukurova evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Çukurova nakliyat firmaları.', 'Çukurova, Adana''nın yeni ve yüksek katlı site bölgesi. Huzurevleri, Toros, Yüzüncüyıl ve Kurttepe''de taşınmalar genellikle asansörlü ve rezidans kurallarına tabi.', '<p>Çukurova''daki sitelerde taşınma için önceden yönetimden izin alınması, çoğu zaman da belirli saat aralığında çalışılması isteniyor. Adana nakliye firmaları bu bölgede işe başlamadan önce site yönetimiyle görüşür ve asansör kullanımı için koruyucu örtü serer. 10. kat üzerindeki dairelerde dış cephe asansörünün boyu kritik; teklif alırken kaçıncı katta olduğunuzu mutlaka belirtin. Huzurevleri ve Yüzüncüyıl çevresinde asansör kiralama hizmeti veren firmalar da bulunuyor.</p>', 2, true),
  (3, 1, 'Yüreğir', 'yuregir', 'Yüreğir Evden Eve Nakliyat Firmaları', 'Adana Yüreğir evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Yüreğir nakliyat firmaları.', 'Yüreğir''de sokaklar Seyhan''a göre daha geniş, bu da kamyonun kapı önüne yanaşmasını kolaylaştırıyor. Kışla, Atakent ve Sinanpaşa çevresi en çok taşınma yapılan bölgeler.', '<p>Yüreğir''de müstakil ve az katlı yapı oranı yüksek olduğu için taşımalar genellikle asansörsüz yapılabiliyor; bu da maliyeti düşürüyor. Ancak yeni yapılan sitelerde durum değişiyor, bu binalarda asansörlü taşıma tercih ediliyor. Yüreğir''den Seyhan veya Çukurova''ya taşınacaksanız köprü trafiği nedeniyle sabah erken saatlerde başlanmasını isteyin. Bölgede ofisi bulunan Adana ev taşıma firmaları sayısı merkez ilçelere göre daha az, bu yüzden randevuyu erken almanız iyi olur.</p>', 3, true),
  (4, 1, 'Sarıçam', 'saricam', 'Sarıçam Evden Eve Nakliyat Firmaları', 'Adana Sarıçam evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Sarıçam nakliyat firmaları.', 'Sarıçam son yıllarda hızla büyüyen bir ilçe. Ertuğrulgazi, Şahintepe ve Mehmet Akif Ersoy mahallelerinde yeni konut projeleri nedeniyle taşınma trafiği yoğun.', '<p>Sarıçam''daki TOKİ ve yeni site bölgelerinde bloklar arası mesafe uzun olabiliyor; kamyonun bloğa yanaşamadığı durumlarda ek taşıma bedeli çıkabiliyor. Teklif alırken aracın kapıya kadar girip giremeyeceğini firmaya sorun. Merkeze uzaklık nedeniyle Seyhan merkezli firmalar Sarıçam işlerine yol farkı ekleyebiliyor, bu yüzden bölgede ofisi olan Adana nakliye firmalarından da teklif almanız fiyat avantajı sağlar.</p>', 4, true),
  (5, 1, 'Ceyhan', 'ceyhan', 'Ceyhan Evden Eve Nakliyat Firmaları', 'Adana Ceyhan evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Ceyhan nakliyat firmaları.', 'Ceyhan, Adana merkeze 45 km uzaklıkta kendi nakliyat firmalarına sahip bir ilçe. Namık Kemal, Burhaniye ve Atatürk mahalleleri firma ofislerinin bulunduğu bölgeler.', '<p>Ceyhan''da hem ilçe içi hem de Adana merkeze taşınma talebi yoğun. Merkeze taşınacaksanız yol farkının fiyata dahil olup olmadığını baştan netleştirin, çünkü bazı firmalar bunu ayrı kalem olarak ekliyor. Ceyhan''daki Adana taşıma şirketlerinin bir kısmı aynı zamanda vinç ve lojistik hizmeti de veriyor; ağır makine veya iş yeri taşımanız varsa bu firmalar daha uygun oluyor. İlçedeki firma sayısı sınırlı olduğu için özellikle ay başı ve hafta sonu için randevuyu en az bir hafta önceden alın.</p>', 5, true),
  (6, 1, 'Kozan', 'kozan', 'Kozan Evden Eve Nakliyat Firmaları', 'Adana Kozan evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Kozan nakliyat firmaları.', 'Kozan, Adana''nın kuzeyinde 70 km mesafede. Tufanpaşa, Türkeli ve Şevkiye mahallelerinde faaliyet gösteren yerleşik nakliyat firmaları var.', '<p>Kozan''dan Adana merkeze veya başka bir ile taşınmalarda mesafe fiyatın en belirleyici kalemi. Merkeze taşınıyorsanız hem Kozan''daki firmalardan hem de Seyhan merkezli firmalardan teklif alıp karşılaştırın; bazen merkez firmalarının dönüş yükü olduğu için fiyatı daha uygun çıkabiliyor. Kozan''ın eski mahallelerinde sokaklar dar ve eğimli, bu yüzden büyük kamyon yerine daha küçük araçla iki sefer yapılması gerekebilir. Adana ev taşıma firmaları arasında bu bölgeyi tanıyan biriyle çalışmak zaman kazandırır.</p>', 6, true),
  (7, 1, 'Karaisalı', 'karaisali', 'Karaisalı Evden Eve Nakliyat Firmaları', 'Adana Karaisalı evden eve nakliyat firmaları listesi. Telefon, adres ve puanlarıyla Karaisalı nakliyat firmaları.', 'Karaisalı, Toroslar''ın eteğinde yer alan bir ilçe. Bölgede lojistik ve şehirler arası taşıma ağırlıklı hizmet veriliyor.', '<p>Karaisalı''da yerleşik evden eve nakliyat firması sayısı çok az; taşınmaların büyük bölümü Adana merkezli firmalar tarafından yapılıyor. Merkezden gelen firmalar yol farkı uyguladığı için fiyat merkez içi taşımaya göre biraz daha yüksek oluyor. Dağlık kesimlere taşınacaksanız yol durumunu firmaya önceden bildirin, araç seçimi buna göre yapılır. Bu sayfada listelenen firmanın yanı sıra Seyhan sayfasındaki Adana nakliye firmalarından da teklif alabilirsiniz.</p>', 7, true)
