insert into sss (kapsam, kapsam_id, soru, cevap, sira, aktif) values
  ('genel', NULL, 'Adana''da evden eve nakliyat ne kadar tutar?', 'Fiyat; ev tipi, kat durumu, asansör ihtiyacı ve mesafeye göre değişir. Net rakam için formu doldurup birden fazla firmadan teklif almanız en sağlıklısıdır.', 1, true),
  ('genel', NULL, 'Dış cephe asansörü ne zaman gerekir?', 'Bina asansörü dar olduğunda, koltuk ve dolap gibi büyük parçalar sığmadığında ya da 3. kattan yukarısında yaşıyorsanız dış cephe asansörü kullanılır.', 2, true),
  ('genel', NULL, 'Teklif almak ücretli mi?', 'Hayır. Rehber üzerinden teklif istemek tamamen ücretsizdir ve hiçbir taahhüt altına girmezsiniz.', 3, true),
  ('genel', NULL, 'Eşyalarım kaç günde taşınır?', 'Adana içi standart bir ev taşıması genellikle aynı gün tamamlanır. Şehirler arası taşımalarda mesafeye göre 1-3 gün sürer.', 4, true),
  ('genel', NULL, 'Ambalaj malzemesi fiyata dahil mi?', 'Firmadan firmaya değişiyor. Bazı firmalar koli, streç film ve balonlu naylonu pakete dahil ederken bazıları ayrı fatura ediyor.', 5, true),
  ('genel', NULL, 'Firmam bu listede yok, nasıl eklenir?', 'Firma Ekle sayfasındaki formu doldurmanız yeterli. Bilgileriniz kontrol edildikten sonra yayınlanır.', 6, true);
